'use strict';

// The address handling of ws's WebSocket client: a `string | URL` parameter,
// a URL class taken from require('url'), an evolving `let` assigned from
// both arms of an instanceof test, and the protocol setter that turns
// http(s) into ws(s).
const { URL } = require('url');
const url = require('url');

function describeAddress(address) {
  let parsed;

  if (address instanceof URL) {
    parsed = address;
  } else {
    try {
      parsed = new URL(address);
    } catch (e) {
      throw new SyntaxError(`Invalid URL: ${address}`);
    }
  }

  if (parsed.protocol === 'http:') {
    parsed.protocol = 'ws:';
  } else if (parsed.protocol === 'https:') {
    parsed.protocol = 'wss:';
  }

  return [
    parsed.protocol,
    parsed.hostname,
    parsed.port || 'default',
    parsed.pathname,
    parsed.hash || '-',
    parsed.username || '-'
  ].join(' ');
}

function kind(address) {
  return address instanceof url.URL ? 'URL' : 'string';
}

module.exports = { describeAddress, kind };
